  1→/**
  2→ * Playwright e2e tests for the simple_collaborative exercise flow.
  3→ *
  4→ * Covers:
  5→ * - Collaborative waiting room: player badge, Start button visible to all
  6→ * - Start navigates to /player (not /gm)
  7→ * - Full onboarding: join → waiting room → start as player
  8→ */
  9→import { test, expect, mockParticipant } from "../fixtures/base.fixture";
 10→
 11→// ── Collaborative waiting room ──────────────────────────────────────────
 12→
 13→test.describe("Collaborative waiting room @waiting-room @collaborative", () => {
 14→  const exerciseId = 500;
 15→
 16→  function collabUrl(participantId: string): string {
 17→    return `/waiting-room?exerciseId=${exerciseId}&participantId=${participantId}`;
 18→  }
 19→
 20→  test("shows collaborative mode message", async ({ page, mockApi }) => {
 21→    const me = mockParticipant({ display_name: "Alice", role: "player" });
 22→    mockApi.seed(exerciseId, [me], "simple_collaborative");
 23→    await mockApi.install();
 24→
 25→    await page.goto(collabUrl(me.id));
 26→
 27→    await expect(
 28→      page.getByText("Collaborative exercise — no facilitator needed."),
 29→    ).toBeVisible();
 30→  });
 31→
 32→  test("shows error when no scenario roles loaded", async ({
 33→    page,
 34→    mockApi,
 35→  }) => {
 36→    const me = mockParticipant({ display_name: "Alice", role: "player" });
 37→    // Only seed participants, explicitly set exercise with no scenario
 38→    mockApi.rooms.set(exerciseId, [me]);
 39→    mockApi.seedExercise(exerciseId, "simple_collaborative", null);
 40→    await mockApi.install();
 41→
 42→    await page.goto(collabUrl(me.id));
 43→
 44→    // No roles → error message shown
 45→    await expect(page.getByText("Scenario has no roles defined")).toBeVisible();
 46→  });
 47→
 48→  test("Start button shows participant count and is visible to any player", async ({
 49→    page,
 50→    mockApi,
 51→  }) => {
 52→    const alice = mockParticipant({ display_name: "Alice", role: "player" });
 53→    const bob = mockParticipant({ display_name: "Bob", role: "player" });
 54→    mockApi.seed(exerciseId, [alice, bob], "simple_collaborative");
 55→    await mockApi.install();
 56→
 57→    await page.goto(collabUrl(alice.id));
 58→
 59→    await expect(
 60→      page.getByRole("button", { name: /Start Exercise \(2\)/ }),
 61→    ).toBeVisible();
 62→  });
 63→
 64→  test("Start button is enabled when all role slots are filled", async ({
 65→    page,
 66→    mockApi,
 67→  }) => {
 68→    const me = mockParticipant({ display_name: "Alice", role: "player" });
 69→    // 1 participant, 1 derived role (player) → all slots filled
 70→    mockApi.seed(exerciseId, [me], "simple_collaborative");
 71→    await mockApi.install();
 72→
 73→    await page.goto(collabUrl(me.id));
 74→
 75→    await expect(
 76→      page.getByRole("button", { name: /Start Exercise/ }),
 77→    ).toBeEnabled();
 78→  });
 79→
 80→  test("clicking Start Exercise navigates to /player", async ({
 81→    page,
 82→    mockApi,
 83→  }) => {
 84→    const me = mockParticipant({ display_name: "Alice", role: "player" });
 85→    mockApi.seed(exerciseId, [me], "simple_collaborative");
 86→    await mockApi.install();
 87→
 88→    await page.goto(collabUrl(me.id));
 89→    await page.getByRole("button", { name: /Start Exercise/ }).click();
 90→
 91→    await expect(page).toHaveURL(/\/player/);
 92→    await expect(page).toHaveURL(new RegExp(`exerciseId=${exerciseId}`));
 93→  });
 94→
 95→  test("does NOT navigate to /gm on start", async ({ page, mockApi }) => {
 96→    const me = mockParticipant({ display_name: "Alice", role: "player" });
 97→    mockApi.seed(exerciseId, [me], "simple_collaborative");
 98→    await mockApi.install();
 99→
100→    await page.goto(collabUrl(me.id));
101→    await page.getByRole("button", { name: /Start Exercise/ }).click();
102→
103→    await expect(page).not.toHaveURL(/\/gm/);
104→  });
105→
106→  test("all participants shown with names", async ({ page, mockApi }) => {
107→    const players = [
108→      mockParticipant({ display_name: "Alice", role: "co" }),
109→      mockParticipant({ display_name: "Bob", role: "nav" }),
110→      mockParticipant({ display_name: "Charlie", role: "ops" }),
111→    ];
112→    mockApi.seed(exerciseId, players, "simple_collaborative");
113→    await mockApi.install();
114→
115→    await page.goto(collabUrl(players[0].id));
116→
117→    await expect(page.getByText("Alice")).toBeVisible();
118→    await expect(page.getByText("Bob")).toBeVisible();
119→    await expect(page.getByText("Charlie")).toBeVisible();
120→  });
121→});
