  1→import type { WritableSignal } from "@angular/core";
  2→import type { AdvisorRecommendation } from "../../shared/advisor-bubbles.component";
  3→import { DecisionApiService } from "../../core/decision-api.service";
  4→import type {
  5→  ActiveDecision,
  6→  ScenarioContext,
  7→} from "../../core/decision-api.service";
  8→import type { RoleDef } from "../../core/scenario-api.service";
  9→import { ExerciseStore } from "../../core/exercise.store";
 10→import type { RoleRecommendation } from "../../shared/all-advisors-panel.component";
 11→
 12→type SubmitEvent = { selectedOptions: string[]; freeText: string };
 13→
 14→export function buildAdvisorRecs(
 15→  decision: ActiveDecision,
 16→  roles: Pick<RoleDef, "id" | "label">[],
 17→): AdvisorRecommendation[] {
 18→  const recs = decision.recommendations || {};
 19→  return Object.entries(recs).map(([key, oid]) => {
 20→    const colonIdx = key.indexOf(":");
 21→    if (colonIdx !== -1) {
 22→      const roleId = key.slice(colonIdx + 1);
 23→      const roleInfo = roles.find((r) => r.id === roleId);
 24→      return {
 25→        participantId: key,
 26→        participantName: roleInfo?.label ?? roleId,
 27→        optionId: oid,
 28→      };
 29→    }
 30→    return { participantId: key, participantName: key, optionId: oid };
 31→  });
 32→}
 33→
 34→export function getScenarioAdvisorRoles(
 35→  roles: RoleDef[],
 36→): Pick<RoleDef, "id" | "label">[] {
 37→  return roles.filter((r) => r.player_type === "advisor");
 38→}
 39→
 40→export function submitRecommendation(
 41→  api: DecisionApiService,
 42→  exerciseId: number,
 43→  decision: ActiveDecision,
 44→  participantId: string,
 45→  event: SubmitEvent,
 46→): void {
 47→  const optionId = event.selectedOptions[0];
 48→  if (!optionId) return;
 49→  api
 50→    .submitRecommendation(exerciseId, decision.id, optionId, participantId)
 51→    .subscribe();
 52→}
 53→
 54→export function submitRoleRecommendation(
 55→  api: DecisionApiService,
 56→  exerciseId: number,
 57→  decision: ActiveDecision,
 58→  participantId: string,
 59→  rec: RoleRecommendation,
 60→): void {
 61→  const optionId = rec.selectedOptions[0];
 62→  if (!optionId) return;
 63→  api
 64→    .submitRecommendation(
 65→      exerciseId,
 66→      decision.id,
 67→      optionId,
 68→      participantId,
 69→      rec.roleId,
 70→    )
 71→    .subscribe();
 72→}
 73→
 74→export function submitDecision(
 75→  api: DecisionApiService,
 76→  store: InstanceType<typeof ExerciseStore>,
 77→  exerciseId: number,
 78→  decision: ActiveDecision,
 79→  event: SubmitEvent,
 80→): void {
 81→  api
 82→    .closeEngineDecision(exerciseId, decision.id, event.selectedOptions)
 83→    .subscribe({
 84→      next: () => store.closeDecision(decision.id),
 85→    });
 86→}
 87→
 88→export function resolvePlayerRole(
 89→  ctx: ScenarioContext,
 90→  role: string,
 91→  gameMode: string,
 92→  store: InstanceType<typeof ExerciseStore>,
 93→  roleLabel: WritableSignal<string>,
 94→): void {
 95→  store.setContext(ctx);
 96→  if (!gameMode && ctx.roles && ctx.roles.length > 0) {
 97→    store.setGameMode("simple_collaborative");
 98→  }
 99→  const roleInfo = ctx.roles?.find((r) => r.id === role);
100→  if (roleInfo) {
101→    store.setPlayerType(roleInfo.player_type);
102→    roleLabel.set(roleInfo.label);
103→  } else if (role === "all_advisors") {
104→    store.setPlayerType("advisor");
105→    roleLabel.set("All Advisors");
106→  } else if (role === "decision_maker") {
107→    store.setPlayerType("decision_maker");
108→    roleLabel.set("Decision Maker");
109→  } else if (role === "solo_player") {
110→    store.setPlayerType("decision_maker");
111→    roleLabel.set("Solo Player");
112→  }
113→}
