  1→import { inject, Injectable } from "@angular/core";
  2→import { HttpClient } from "@angular/common/http";
  3→import { Observable } from "rxjs";
  4→import { environment } from "./environment";
  5→import type { RoleDef } from "./scenario-api.service";
  6→
  7→export type { RoleDef as RoleInfo } from "./scenario-api.service";
  8→
  9→export interface DecisionOption {
 10→  id: string;
 11→  label: string;
 12→  score?: number;
 13→  role?: string | null;
 14→}
 15→
 16→export interface ActiveDecision {
 17→  id: string;
 18→  event_id: string | null;
 19→  issue_id: string | null;
 20→  title: string;
 21→  description: string;
 22→  question_type: string;
 23→  options: DecisionOption[];
 24→  completion_mode: string;
 25→  target_roles: string[];
 26→  timeout_ms: number;
 27→  max_selections: number | null;
 28→  status: string;
 29→  opened_at_pt_ms: number;
 30→  closed_at_pt_ms: number | null;
 31→  recommendations: Record<string, string>;
 32→  selected_option_ids: string[];
 33→}
 34→
 35→export interface DecisionSubmission {
 36→  participant_id: string;
 37→  participant_name: string;
 38→  selected_options: string[] | null;
 39→  free_text: string | null;
 40→}
 41→
 42→export interface DecisionResponseItem {
 43→  id: number;
 44→  participant_name: string;
 45→  selected_options: string[] | null;
 46→  free_text: string | null;
 47→  score: number | null;
 48→  submitted_at: string;
 49→}
 50→
 51→export interface DecisionDetail {
 52→  id: number;
 53→  exercise_id: number;
 54→  issue_id: string;
 55→  title: string;
 56→  description: string;
 57→  question_type: string;
 58→  options: DecisionOption[] | null;
 59→  completion_mode: string;
 60→  status: string;
 61→  created_at: string;
 62→  closed_at: string | null;
 63→  responses: DecisionResponseItem[];
 64→}
 65→
 66→export interface ScenarioContext {
 67→  title: string;
 68→  description: string;
 69→  briefing: string;
 70→  objectives: string[];
 71→  rules: string[];
 72→  roles: RoleDef[];
 73→  score_tier_thresholds?: Record<string, number>;
 74→}
 75→
 76→@Injectable({ providedIn: "root" })
 77→export class DecisionApiService {
 78→  private readonly http = inject(HttpClient);
 79→  private readonly base = environment.apiBaseUrl;
 80→
 81→  /** Get open decisions from the engine */
 82→  getEngineDecisions(exerciseId: number): Observable<ActiveDecision[]> {
 83→    return this.http.get<ActiveDecision[]>(
 84→      `${this.base}/api/exercises/${exerciseId}/engine/decisions`,
 85→    );
 86→  }
 87→
 88→  /** Submit a response to a DB-persisted decision */
 89→  submitResponse(
 90→    decisionId: number,
 91→    submission: DecisionSubmission,
 92→  ): Observable<DecisionResponseItem> {
 93→    return this.http.post<DecisionResponseItem>(
 94→      `${this.base}/api/decisions/${decisionId}/responses`,
 95→      submission,
 96→    );
 97→  }
 98→
 99→  /** Get decision details with all responses (for GM observation) */
100→  getDecisionDetail(decisionId: number): Observable<DecisionDetail> {
101→    return this.http.get<DecisionDetail>(
102→      `${this.base}/api/decisions/${decisionId}`,
103→    );
104→  }
105→
106→  /** List all decisions for an exercise */
107→  listDecisions(
108→    exerciseId: number,
109→    status?: string,
110→  ): Observable<DecisionDetail[]> {
111→    const params: Record<string, string | number> = { exercise_id: exerciseId };
112→    if (status) {
113→      params["status"] = status;
114→    }
115→    return this.http.get<DecisionDetail[]>(`${this.base}/api/decisions`, {
116→      params,
117→    });
118→  }
119→
120→  /** Submit an advisor recommendation on an open decision */
121→  submitRecommendation(
122→    exerciseId: number,
123→    decisionId: string,
124→    optionId: string,
125→    participantId: string,
126→    roleId?: string,
127→  ): Observable<unknown> {
128→    const body: Record<string, string> = {
129→      decision_id: decisionId,
130→      option_id: optionId,
131→      participant_id: participantId,
132→    };
133→    if (roleId) {
134→      body["role_id"] = roleId;
135→    }
136→    return this.http.post(
137→      `${this.base}/api/exercises/${exerciseId}/engine/decisions/recommend`,
138→      body,
139→    );
140→  }
141→
142→  /** Close a decision in the engine (GM or decision-maker action) */
143→  closeEngineDecision(
144→    exerciseId: number,
145→    decisionId: string,
146→    selectedOptionIds: string[] = [],
147→  ): Observable<unknown> {
148→    return this.http.post(
149→      `${this.base}/api/exercises/${exerciseId}/engine/decisions/${decisionId}/close`,
150→      { selected_option_ids: selectedOptionIds },
151→    );
152→  }
153→
154→  /** Get scenario context/reference info */
155→  getContext(exerciseId: number): Observable<ScenarioContext> {
156→    return this.http.get<ScenarioContext>(
157→      `${this.base}/api/exercises/${exerciseId}/engine/context`,
158→    );
159→  }
160→}
