 69→export class AllAdvisorsPanelComponent {
 70→  readonly roles = input.required<AdvisorRoleTab[]>();
 71→  readonly decisionTitle = input.required<string>();
 72→  readonly decisionDescription = input<string>("");
 73→  readonly questionType = input.required<string>();
 74→  readonly options = input<DecisionOption[]>([]);
 75→  readonly submitted = output<RoleRecommendation>();
 76→  readonly closed = output();
 77→
 78→  protected readonly activeTab = signal("");
 79→  private readonly submittedRoles = signal<Set<string>>(new Set());
 80→
 81→  constructor() {
 82→    effect(() => {
 83→      const roles = this.roles();
 84→      if (roles.length > 0 && !this.activeTab()) {
 85→        this.activeTab.set(roles[0].id);
 86→      }
 87→    });
 88→  }
 89→
 90→  protected isSubmitted(roleId: string): boolean {
 91→    return this.submittedRoles().has(roleId);
 92→  }
 93→
 94→  protected onRoleSubmit(
 95→    roleId: string,
 96→    event: { selectedOptions: string[]; freeText: string },
 97→  ): void {
 98→    const updated = new Set(this.submittedRoles());
 99→    updated.add(roleId);
100→    this.submittedRoles.set(updated);
101→    this.submitted.emit({
102→      roleId,
103→      selectedOptions: event.selectedOptions,
104→      freeText: event.freeText,
105→    });
106→    // Auto-advance to next unsubmitted role
107→    const next = this.roles().find((r) => !updated.has(r.id));
108→    if (next) {
109→      this.activeTab.set(next.id);
110→    }
111→  }
112→}
