100→    activeIssues: computed(() =>
101→      store.issues().filter((i) => i.lifecycle === "active"),
102→    ), // active defects
103→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
104→    decisionCountdownMs: computed(() => {
105→      const decision = store
106→        .decisions()
107→        .find((d) => d.status === "open" && d.timeout_ms > 0);
108→      if (!decision) return null;
109→      const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
110→      return Math.max(0, deadline - store.playTimeMs());
111→    }),
112→    /** Countdown clock: decision timer when a decision is open, otherwise time to next event. */
113→    turnCountdownClock: computed(() => {
114→      // Prefer decision countdown when an open decision has a timeout
115→      const decision = store
116→        .decisions()
117→        .find((d) => d.status === "open" && d.timeout_ms > 0);
118→      if (decision) {
119→        const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
120→        return formatTimeMs(Math.max(0, deadline - store.playTimeMs()));
121→      }
122→      const pt = store.playTimeMs();
123→      const nextEvent = store
124→        .events()
125→        .filter((e) => e.lifecycle === "scheduled" && e.scheduled_pt_ms > pt)
126→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
127→      if (!nextEvent) return null;
128→      const remaining = Math.max(0, nextEvent.scheduled_pt_ms - pt);
129→      return formatTimeMs(remaining);
130→    }),
131→    issuesWithCountdown: computed(() => {
132→      const pt = store.playTimeMs();
133→      return store
134→        .issues()
135→        .filter(
136→          (i) =>
137→            i.lifecycle === "active" &&
138→            i.auto_resolve_ms > 0 &&
139→            i.activated_at_pt_ms !== null,
140→        )
141→        .map((i) => {
142→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
143→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
144→          return { ...i, remaining_ms: remaining };
145→        });
146→    }),
147→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
148→    openDecisions: computed(() =>
149→      store.decisions().filter((d) => d.status === "open"),
150→    ),
151→    hasOpenDecision: computed(
152→      () => store.decisions().filter((d) => d.status === "open").length > 0,
153→    ),
154→    connectedParticipants: computed(() =>
155→      store.participants().filter((p) => p.connected),
156→    ),
157→    connectedCount: computed(
